python3 << 'EOF'
import json, glob, os
from datetime import datetime

base = '/Users/sudnya/.claude/projects/-Users-sudnya-checkout-smi-gfx-challenge/'
files = sorted(glob.glob(base + '*.jsonl'))

def extract_user_text(msg):
    """Return user prompt text if this is a typed prompt, else None."""
    content = msg.get('content')
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        # Skip if any tool_result (tool result, not a typed prompt)
        if any(isinstance(c, dict) and c.get('type') == 'tool_result' for c in content):
            return None
        texts = [c.get('text','') for c in content if isinstance(c, dict) and c.get('type') == 'text']
        if texts:
            return '\n'.join(texts)
    return None

def extract_assistant_text(msg):
    """Return assistant text content (concatenated), no thinking, no tool_use."""
    content = msg.get('content')
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        texts = [c.get('text','') for c in content if isinstance(c, dict) and c.get('type') == 'text']
        return '\n'.join(t for t in texts if t)
    return ''

def extract_tool_uses(msg):
    """Return list of tool_use names from an assistant message."""
    content = msg.get('content')
    out = []
    if isinstance(content, list):
        for c in content:
            if isinstance(c, dict) and c.get('type') == 'tool_use':
                out.append(c.get('name', '?'))
    return out

sessions_out = []

for f in files:
    sid = os.path.basename(f).replace('.jsonl','')
    records = []
    with open(f) as fp:
        for line in fp:
            try:
                records.append(json.loads(line))
            except:
                pass

    # Collect user/assistant messages in order, ignoring sidechain (subagent) traffic
    main_msgs = [r for r in records if r.get('type') in ('user','assistant') and not r.get('isSidechain', False)]

    # Find ai-title for context
    title = None
    for r in records:
        if r.get('type') == 'ai-title':
            title = r.get('title') or r.get('aiTitle') or None
            break

    started_at = None
    if main_msgs:
        started_at = main_msgs[0].get('timestamp')

    turns = []
    current_prompt = None
    current_response_parts = []
    current_tool_calls = []

    def flush():
        if current_prompt is not None:
            turns.append({
                'prompt': current_prompt['text'],
                'prompt_timestamp': current_prompt['ts'],
                'response_text': '\n\n'.join(p for p in current_response_parts if p),
                'assistant_tool_calls': current_tool_calls.copy(),
            })

    for r in main_msgs:
        msg = r.get('message', {})
        if r.get('type') == 'user':
            txt = extract_user_text(msg)
            if txt is not None:
                # Start new turn — flush previous
                flush()
                current_prompt = {'text': txt, 'ts': r.get('timestamp')}
                current_response_parts = []
                current_tool_calls = []
            # tool_result user messages are skipped (they're tool feedback, not prompts)
        elif r.get('type') == 'assistant':
            t = extract_assistant_text(msg)
            if t:
                current_response_parts.append(t)
            tc = extract_tool_uses(msg)
            if tc:
                current_tool_calls.extend(tc)

    flush()

    sessions_out.append({
        'session_id': sid,
        'session_file': os.path.basename(f),
        'started_at': started_at,
        'ai_title': title,
        'turn_count': len(turns),
        'turns': turns,
    })

# Sort sessions by start time
sessions_out.sort(key=lambda s: s['started_at'] or '')

out = {
    'project': 'gfx-challenge',
    'project_path': '/Users/sudnya/checkout/smi/gfx-challenge',
    'exported_at': datetime.utcnow().isoformat() + 'Z',
    'source_dir': base,
    'session_count': len(sessions_out),
    'total_user_prompts': sum(s['turn_count'] for s in sessions_out),
    'sessions': sessions_out,
}

out_path = '/Users/sudnya/checkout/smi/gfx-challenge/claude_code_session_history.json'
with open(out_path, 'w') as fp:
    json.dump(out, fp, indent=2, ensure_ascii=False)

print(f"Wrote {out_path}")
print(f"Sessions: {out['session_count']}")
print(f"Total user prompts: {out['total_user_prompts']}")
print(f"File size: {os.path.getsize(out_path):,} bytes")
print()
print("Per-session summary:")
for s in sessions_out:
    print(f"  {s['started_at']}  {s['session_id'][:8]}  turns={s['turn_count']}  title={s['ai_title']!r}")
